def solve(WELL_FORMED):
    chain = []
    for token in WELL_FORMED:
        if token == 'a':
            chain.append('a')
        else:
            chain.append(token)
    return chain

def main():
    WELL_FORMED = 'aabbccddd'
    chain = solve(WELL_FORMED)
    print(','.join(chain))

if __name__ == "__main__":
    main()
